# owner: platform
import unittest

from hourglass.timesheet import timesheet_lines
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError


def make_shift(worker, start, end, day="mon"):
    return Shift(worker, day, Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_one_line_per_worker_busiest_first(self):
        shifts = [
            make_shift("Bo", 9, 13),
            make_shift("Ana", 9, 17),
            make_shift("Ana", 9, 13, "tue"),
            make_shift("Cy", 9, 10)
        ]
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Ana: 2 shifts, 12.0 hours",
                "Bo: 1 shifts, 4.0 hours",
                "Cy: 1 shifts, 1.0 hours"
            ]
        )

    def test_hours_use_one_decimal(self):
        shift = Shift("Ana", "mon", Span(540, 620))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Ana: 1 shifts, 1.3 hours"]
        )

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker_raises(self):
        for blank in ("", "   "):
            with self.assertRaises(ProjectError):
                timesheet_lines([make_shift(blank, 9, 10)])
